from __future__ import annotations

from pydantic import Field
from typing_extensions import NotRequired, TypedDict

from ..core import UNSET, Optional, SdkBaseModel


class DonationCampaignNonprofitCause2(SdkBaseModel):
    """The nonprofit cause that the campaign supports."""

    banner_url: Optional[str] = Field(default=UNSET, alias="bannerUrl")
    """The URL to the banner showing the cause that the nonprofit organization supports."""

    cause_id: Optional[str] = Field(default=UNSET, alias="causeId")
    """The unique identifier of the nonprofit cause. This value is generated by Adyen."""

    description: Optional[str] = UNSET
    """The description of the cause that the nonprofit supports."""

    global_website_url: Optional[str] = Field(default=UNSET, alias="globalWebsiteUrl")
    """The URL to the website of the nonprofit organization."""

    goals: Optional[list[str]] = UNSET
    """The United Nations Sustainable Development Goals (UN SDGs) supported by the nonprofit organization, specified in
    the format ``unsdg_<number>``, where the number is the number of the UN SDG. For example, **unsdg_1**."""

    logo_url: Optional[str] = Field(default=UNSET, alias="logoUrl")
    """The URL to the logo of the nonprofit organization."""

    nonprofit_name: Optional[str] = Field(default=UNSET, alias="nonprofitName")
    """The name of the nonprofit organization."""

    terms_and_conditions_url: Optional[str] = Field(default=UNSET, alias="termsAndConditionsUrl")
    """The URL to the terms and conditions of the nonprofit organization."""


class DonationCampaignNonprofitCause2Dict(TypedDict):
    banner_url: NotRequired[str]
    cause_id: NotRequired[str]
    description: NotRequired[str]
    global_website_url: NotRequired[str]
    goals: NotRequired[list[str]]
    logo_url: NotRequired[str]
    nonprofit_name: NotRequired[str]
    terms_and_conditions_url: NotRequired[str]
